const { createHash } = require("node:crypto");
const platforms = ["linux-x64", "windows-x64", "macos-universal"];
const caskPath = "Casks/aperture-preview.rb";
const sha256 = (data) => createHash("sha256").update(data).digest("hex");

function cask({ repository, tag, checksum, sequence }) {
  if (
    !/^[\w.-]+\/[\w.-]+$/.test(repository) ||
    !/^pr-\d+-[a-f0-9]{40}$/.test(tag) ||
    !/^[a-f0-9]{64}$/.test(checksum) ||
    !Number.isSafeInteger(sequence) ||
    sequence < 1
  )
    throw Error("Invalid cask metadata");
  return `# Generated by the trusted PR release publisher. Do not edit manually.
# build-run-number: ${sequence}
cask "aperture-preview" do
  version "0.0.${sequence}"
  sha256 "${checksum}"

  url "https://github.com/${repository}/releases/download/${tag}/Aperture-macos-universal.zip"
  name "Aperture Preview"
  desc "Local-first financial research desktop app (PR preview)"
  homepage "https://github.com/${repository}"

  livecheck do
    skip "Updated by successful PR release builds"
  end

  depends_on macos: :big_sur
  container nested: "Aperture-macos-universal.dmg"
  app "Aperture.app"

  caveats <<~EOS
    This preview contains unmerged PR code and is not a stable release.
    Builds are not Developer ID signed or notarized. macOS may block launch.
    This cask installs Aperture.app; it does not erase your workspace data.
  EOS
end
`;
}

// Only the Mac build feeds Homebrew, so it is the one required artifact. A
// slow or failed Linux/Windows build must not hold back the Homebrew update.
const required = new Set(["macos-universal"]);
const labels = {
  "macos-universal": "universal Mac (Intel + Apple Silicon)",
  "windows-x64": "Windows x64 installer",
  "linux-x64": "Linux x64 DEB and AppImage",
};

function selectArtifacts(artifacts) {
  return platforms.flatMap((platform) => {
    const matches = artifacts.filter(
      (a) => a.name === `Aperture-${platform}`,
    );
    if (!matches.length && !required.has(platform)) return [];
    if (
      matches.length !== 1 ||
      matches[0].expired ||
      matches[0].size_in_bytes <= 0 ||
      matches[0].size_in_bytes > 500 * 1024 * 1024
    )
      throw Error(
        `Missing, duplicate, expired or oversized ${platform} artifact`,
      );
    return [matches[0]];
  });
}

async function optional(fn) {
  try {
    return (await fn()).data;
  } catch (error) {
    if (error.status === 404) return null;
    throw error;
  }
}

async function updateTap({ github, context, core, run, pr, tag, checksum }) {
  const repository = `${context.repo.owner}/${context.repo.repo}`;
  // Forks get downloadable prereleases, but do not replace the Homebrew channel.
  if (pr.head.repo?.full_name !== repository || pr.draft) {
    core.info(
      "Tap unchanged: only non-draft, same-repository PRs advance the preview channel.",
    );
    return;
  }
  const branch = context.payload.repository.default_branch;
  for (let attempt = 0; attempt < 4; attempt++) {
    const current = await optional(() =>
      github.rest.repos.getContent({
        ...context.repo,
        path: caskPath,
        ref: branch,
      }),
    );
    const previous = current
      ? Buffer.from(current.content, "base64").toString("utf8")
      : "";
    const marker = previous.match(/^# build-run-number: (\d+)$/m);
    if (current && !marker)
      throw Error("Refusing to overwrite an unmanaged cask");
    const sequence = Number(marker?.[1] || 0);
    if (sequence >= run.run_number) {
      core.info("Tap already points to this or a newer build.");
      return;
    }
    const content = cask({
      repository,
      tag,
      checksum,
      sequence: run.run_number,
    });
    try {
      await github.rest.repos.createOrUpdateFileContents({
        ...context.repo,
        branch,
        path: caskPath,
        message: `Update Homebrew preview to PR #${pr.number} (${run.head_sha.slice(0, 8)})`,
        content: Buffer.from(content).toString("base64"),
        ...(current ? { sha: current.sha } : {}),
      });
      core.info(`Homebrew preview updated to ${tag}`);
      return;
    } catch (error) {
      // Another PR can finish at the same time. Re-read, never force-write.
      if (![409, 422].includes(error.status) || attempt === 3) throw error;
    }
  }
}

async function publish({ github, context, core, runId }) {
  if (!Number.isSafeInteger(runId) || runId < 1)
    throw Error("A valid build run ID is required");
  const repository = `${context.repo.owner}/${context.repo.repo}`;
  const { data: run } = await github.rest.actions.getWorkflowRun({
    ...context.repo,
    run_id: runId,
  });
  const { data: workflow } = await github.rest.actions.getWorkflow({
    ...context.repo,
    workflow_id: "pr-desktop-builds.yml",
  });
  if (
    run.workflow_id !== workflow.id ||
    run.event !== "pull_request" ||
    run.conclusion !== "success" ||
    run.status !== "completed" ||
    run.repository.full_name !== repository ||
    !/^[a-f0-9]{40}$/.test(run.head_sha)
  )
    throw Error(
      "Only successful PR desktop builds from this repository can publish",
    );
  // Fork workflow_run payloads can omit pull_requests; resolve through the API.
  let candidates = run.pull_requests || [];
  if (!candidates.length)
    candidates = await github.paginate(
      github.rest.repos.listPullRequestsAssociatedWithCommit,
      { ...context.repo, commit_sha: run.head_sha, per_page: 100 },
    );
  const prs = [];
  for (const candidate of candidates) {
    const { data: pr } = await github.rest.pulls.get({
      ...context.repo,
      pull_number: candidate.number,
    });
    if (
      pr.base.repo.full_name === repository &&
      pr.head.sha === run.head_sha &&
      pr.head.repo?.full_name === run.head_repository?.full_name &&
      (pr.state === "open" || pr.merged)
    )
      prs.push(pr);
  }
  if (!prs.length) {
    core.info(
      "No current PR head matches this build; skipping obsolete or closed PR.",
    );
    return;
  }
  const artifacts = selectArtifacts(
    await github.paginate(github.rest.actions.listWorkflowRunArtifacts, {
      ...context.repo,
      run_id: runId,
      per_page: 100,
    }),
  );
  for (const pr of prs) {
    const tag = `pr-${pr.number}-${run.head_sha}`;
    const ref = await optional(() =>
      github.rest.git.getRef({ ...context.repo, ref: `tags/${tag}` }),
    );
    if (ref && ref.object.sha !== run.head_sha)
      throw Error("Existing release tag does not match the built commit");
    let release = await optional(() =>
      github.rest.repos.getReleaseByTag({ ...context.repo, tag }),
    );
    if (!release)
      release = (
        await github.paginate(github.rest.repos.listReleases, {
          ...context.repo,
          per_page: 100,
        })
      ).find((r) => r.tag_name === tag);
    let checksum;
    if (release && !release.draft) {
      // Published releases are immutable. Re-running may repair a failed tap update.
      checksum = release.body?.match(
        /<!-- macos-sha256: ([a-f0-9]{64}) -->/,
      )?.[1];
      if (!release.prerelease || !checksum)
        throw Error("Existing release is not a managed PR preview");
      core.info(`Already published: ${release.html_url}`);
    } else {
      if (!release) {
        ({ data: release } = await github.rest.repos.createRelease({
          ...context.repo,
          tag_name: tag,
          target_commitish: run.head_sha,
          name: `PR #${pr.number} preview · ${run.head_sha.slice(0, 8)}`,
          body: "Uploading installers; this release is not ready yet.",
          draft: true,
          prerelease: true,
          make_latest: "false",
        }));
      }
      const hashes = [];
      for (const artifact of artifacts) {
        const archive = await github.rest.actions.downloadArtifact({
          ...context.repo,
          artifact_id: artifact.id,
          archive_format: "zip",
        });
        const data = Buffer.from(archive.data);
        const digest = sha256(data);
        if (artifact.digest && artifact.digest !== `sha256:${digest}`)
          throw Error("Artifact checksum mismatch");
        const name = `${artifact.name}.zip`;
        const old = (
          await github.paginate(github.rest.repos.listReleaseAssets, {
            ...context.repo,
            release_id: release.id,
            per_page: 100,
          })
        ).find((a) => a.name === name);
        if (old)
          await github.rest.repos.deleteReleaseAsset({
            ...context.repo,
            asset_id: old.id,
          });
        await github.rest.repos.uploadReleaseAsset({
          ...context.repo,
          release_id: release.id,
          name,
          data,
          headers: {
            "content-type": "application/zip",
            "content-length": data.length,
          },
        });
        hashes.push(`${digest}  ${name}`);
        if (artifact.name === "Aperture-macos-universal") checksum = digest;
      }
      const body = [
        `Preview of [PR #${pr.number}](https://github.com/${repository}/pull/${pr.number}). Contains unmerged code; not a stable release.`,
        `Built commit: \`${run.head_sha}\``,
        `Build: https://github.com/${repository}/actions/runs/${run.id}`,
        `Downloads: ${artifacts.map((a) => labels[a.name.replace("Aperture-", "")]).join(", ")}. Unzip the archive for your OS.`,
        "Builds are unsigned/not notarized. Operating systems may warn or block installation. No security settings are changed by this workflow.",
        "SHA-256 checksums:\n```text\n" + hashes.join("\n") + "\n```",
        `<!-- macos-sha256: ${checksum} -->`,
      ].join("\n\n");
      ({ data: release } = await github.rest.repos.updateRelease({
        ...context.repo,
        release_id: release.id,
        body,
        draft: false,
        prerelease: true,
        make_latest: "false",
      }));
      core.info(`Published ${release.html_url}`);
    }
    await core.summary
      .addLink(`PR #${pr.number} installers`, release.html_url)
      .write();
    await updateTap({ github, context, core, run, pr, tag, checksum });
  }
}
module.exports = publish;
module.exports.cask = cask;
module.exports.selectArtifacts = selectArtifacts;
